-- TortoiseBots reply catalog, extracted from the preserved Vanilla/Tortoise data.
-- Source: T-imothy/tortoise-wow, commit 8415f1b9dc079f7207cfaf8589fa135ce19a1ada
-- modules/mod-playerbots/sql/world/ai_playerbot_texts.sql (GPL-2.0-or-later).
-- Only reply/probability rows are ported; donor DROP/CREATE and generated help
-- graphs are not executed. Existing replies and operator probabilities survive.
-- Temporary staging makes retries idempotent without changing persistent schema.

DROP TEMPORARY TABLE IF EXISTS `_tortoisebots_seed_texts`;
CREATE TEMPORARY TABLE `_tortoisebots_seed_texts` LIKE `ai_playerbot_texts`;
SELECT DISTINCT seed.`name`, seed.`text`, seed.`say_type`, seed.`reply_type`, seed.`text_loc1`, seed.`text_loc2`, seed.`text_loc3`, seed.`text_loc4`, seed.`text_loc5`, seed.`text_loc6`, seed.`text_loc7`, seed.`text_loc8`
FROM `_tortoisebots_seed_texts` seed
WHERE NOT EXISTS (SELECT 1 FROM `ai_playerbot_texts` existing WHERE BINARY existing.`name` = BINARY seed.`name` AND BINARY existing.`text` = BINARY seed.`text` AND existing.`say_type` = seed.`say_type` AND existing.`reply_type` = seed.`reply_type`);
DROP TEMPORARY TABLE `_tortoisebots_seed_texts`;

DROP TEMPORARY TABLE IF EXISTS `_tortoisebots_seed_texts_chance`;
CREATE TEMPORARY TABLE `_tortoisebots_seed_texts_chance` LIKE `ai_playerbot_texts_chance`;
SELECT DISTINCT seed.`name`, seed.`probability`
FROM `_tortoisebots_seed_texts_chance` seed
WHERE NOT EXISTS (SELECT 1 FROM `ai_playerbot_texts_chance` existing WHERE existing.`name` = seed.`name`);
DROP TEMPORARY TABLE `_tortoisebots_seed_texts_chance`;
